// Normalizes raw complaint records and drops ones already processed in a
// prior cycle. Processed IDs are tracked in GLOBAL workflow static data.
const cfg = $('Set - Config').first().json;
const response = $input.first().json;
const rawComplaints = response.complaints || response.items || response.results || [];

function normalize(c) {
  return {
    complaintId: c.id || c.complaintId || '',
    productName: c.productName || c.product || '',
    batchLot: c.batchLot || c.lot || c.batchNumber || '',
    narrativeText: c.narrative || c.description || c.text || '',
    reportedAt: c.reportedAt || c.date || c.reported_date || null,
    reporterType: c.reporterType || c.source || 'unknown'
  };
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedComplaintIds) staticData.processedComplaintIds = [];
const seenSet = new Set(staticData.processedComplaintIds);

const normalized = rawComplaints.map(normalize);
const newComplaints = normalized.filter(c => c.complaintId && !seenSet.has(c.complaintId));

return [{
  json: {
    ...cfg,
    normalizedComplaints: newComplaints,
    hasNew: newComplaints.length > 0,
    scanTimestamp: new Date().toISOString()
  }
}];

// Splits the normalized complaints into one item per complaint so each
// gets its own AI field-extraction call.
const item = $input.first().json;
const { normalizedComplaints, ...rest } = item;

return normalizedComplaints.map(c => ({
  json: { ...rest, ...c }
}));

