const upstream = $('JS - Fan Out Complaints for Extraction').item.json;
const response = $input.first().json;

let parsed = {
  product: upstream.productName,
  batchLot: upstream.batchLot,
  defectCategory: 'uncategorized',
  severity: 'Moderate',
  extractionNotes: 'AI extraction unavailable this cycle; defaulted to uncategorized/Moderate.'
};
try {
  const raw = String(response.output || response.text || response.response || '{}').replace(/```json|```/g, '').trim();
  const result = JSON.parse(raw);
  parsed = { ...parsed, ...result };
} catch (e) {
  // keep safe default above
}

return [{
  json: {
    ...upstream,
    product: parsed.product,
    batchLot: parsed.batchLot,
    defectCategory: parsed.defectCategory,
    severity: parsed.severity,
    extractionNotes: parsed.extractionNotes
  }
}];

// Aggregates ALL extracted complaint items from this cycle into clusters
// keyed by product + defect category.
const cfg = $('Set - Config').first().json;
const allItems = $input.all().map(i => i.json);

const clusters = {};
for (const c of allItems) {
  const key = `${c.product}||${c.defectCategory}`;
  if (!clusters[key]) {
    clusters[key] = {
      clusterKey: key,
      product: c.product,
      defectCategory: c.defectCategory,
      complaintCount: 0,
      criticalCount: 0,
      complaintIds: [],
      sampleNarratives: []
    };
  }
  clusters[key].complaintCount += 1;
  if (c.severity === 'Critical') clusters[key].criticalCount += 1;
  clusters[key].complaintIds.push(c.complaintId);
  if (clusters[key].sampleNarratives.length < 3) clusters[key].sampleNarratives.push(c.narrativeText);
}

return [{
  json: {
    ...cfg,
    clusters: Object.values(clusters),
    cycleTimestamp: new Date().toISOString()
  }
}];

// Deterministic, non-AI check: compares each cluster's count this cycle
// against its own rolling baseline (mean + std-dev), so a mis-extraction
// can never suppress a real statistical spike. History is kept in
// workflow static data scoped to THIS node.
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.clusterHistory) staticData.clusterHistory = {};

const rollingCycles = item.rollingBaselineCycles || 14;
const zThreshold = item.spikeZScoreThreshold || 2;

function meanStd(values) {
  if (!values.length) return { mean: 0, std: 0 };
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const variance = values.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / values.length;
  return { mean, std: Math.sqrt(variance) };
}

const scoredClusters = (item.clusters || []).map(cluster => {
  const history = (staticData.clusterHistory[cluster.clusterKey] || []).slice(-rollingCycles);
  const { mean, std } = meanStd(history);
  let zScore = 0;
  let isStatisticalAnomaly = false;
  if (history.length >= 3 && std > 0) {
    zScore = (cluster.complaintCount - mean) / std;
    isStatisticalAnomaly = zScore >= zThreshold && cluster.complaintCount > mean;
  }

  // Append this cycle's count for next cycle's comparison.
  staticData.clusterHistory[cluster.clusterKey] = [...history, cluster.complaintCount];

  return {
    ...cluster,
    baselineMean: Math.round(mean * 10) / 10,
    zScore: Math.round(zScore * 100) / 100,
    isStatisticalAnomaly
  };
});

return [{ json: { ...item, scoredClusters } }];

// Splits the scored clusters into one item per cluster so each gets
// routed and logged individually.
const item = $input.first().json;
const { scoredClusters, clusters, ...rest } = item;

return scoredClusters.map(cluster => ({
  json: { ...rest, ...cluster }
}));
